    private int obtenerColorArea(String area) {
        if (area == null) return Color.parseColor("#B6B9C2");
        String a = area.toLowerCase().trim();

        // Isla del Conocimiento / Todas las áreas - Amarillo
        if (a.contains("conocimiento") || a.contains("isla") ||
                (a.contains("todas") && (a.contains("area") || a.contains("área")))) {
            return ContextCompat.getColor(this, R.color.area_conocimiento);
        }

        if (a.contains("matem")) return ContextCompat.getColor(this, R.color.area_matematicas);
        if (a.contains("lengua") || a.contains("lectura") || a.contains("espa") || a.contains("critica"))
            return ContextCompat.getColor(this, R.color.area_lenguaje);
        if (a.contains("social") || a.contains("ciudad"))
            return ContextCompat.getColor(this, R.color.area_sociales);
        if (a.contains("cien") || a.contains("biolo") || a.contains("fis") || a.contains("quim"))
            return ContextCompat.getColor(this, R.color.area_ciencias);
        if (a.contains("ingl"))
            return ContextCompat.getColor(this, R.color.area_ingles);

        return Color.parseColor("#B6B9C2");
    }

    private int obtenerColorAreaSoft(String area) {
        if (area == null) return Color.parseColor("#BA68C8");
        String a = area.toLowerCase().trim();

        if (a.contains("matem")) return ContextCompat.getColor(this, R.color.area_matematicas_soft);
        if (a.contains("lengua") || a.contains("lectura") || a.contains("espa") || a.contains("critica"))
            return ContextCompat.getColor(this, R.color.area_lenguaje_soft);
        if (a.contains("social") || a.contains("ciudad"))
            return ContextCompat.getColor(this, R.color.area_sociales_soft);
        if (a.contains("cien") || a.contains("biolo") || a.contains("fis") || a.contains("quim"))
            return ContextCompat.getColor(this, R.color.area_ciencias_soft);
        if (a.contains("ingl"))
            return ContextCompat.getColor(this, R.color.area_ingles_soft);

        return Color.parseColor("#BA68C8");
    }

    private int dp(int px) {
        return (int) (px * getResources().getDisplayMetrics().density);
    }

    private static String readErr(ResponseBody eb) {
        if (eb == null) return null;
        try { return eb.string(); } catch (IOException ignored) { return null; }
    }

    /**
     * Log utilitario para eventos de IA y preguntas.
     */
    private void logIAEvent(String mensaje, Integer idSesion, String area, String subtema, int nivel, int cantidadPreguntas) {
        String logMsg = "[IA_EVENT] " + mensaje +
                " | idSesion=" + (idSesion != null ? idSesion : "null") +
                ", área=" + (area != null ? area : "null") +
                ", subtema=" + (subtema != null ? subtema : "null") +
                ", nivel=" + nivel +
                ", preguntas=" + cantidadPreguntas;
        android.util.Log.d("QuizActivity", logMsg);
    }

    /**
     *  ANÁLISIS DE CONTENIDO: Determina si las preguntas parecen generadas por IA
     * Analiza patrones típicos de preguntas generadas por OpenAI vs banco estático
     */
    private boolean analizarContenidoPreguntasIA(java.util.List<ApiQuestion> preguntas) {
        if (preguntas == null || preguntas.isEmpty()) return false;

        int indicadoresIA = 0;
        int totalPreguntas = Math.min(3, preguntas.size()); // Analizar máximo 3 preguntas

        for (int i = 0; i < totalPreguntas; i++) {
            ApiQuestion pregunta = preguntas.get(i);
            if (pregunta.enunciado == null) continue;

            String texto = pregunta.enunciado.toLowerCase();

            //  INDICADORES DE IA/OPENAI:
            // 1. Preguntas más elaboradas y contextualizadas
            if (texto.contains("considera") || texto.contains("analiza") ||
                    texto.contains("reflexiona") || texto.contains("evalúa")) {
                indicadoresIA++;
                android.util.Log.d("QuizActivity", "  ✅ Indicador IA: Vocabulario elaborado");
            }

            // 2. Preguntas con contexto narrativo
            if (texto.contains("situación") || texto.contains("contexto") ||
                    texto.contains("escenario") || texto.contains("ejemplo")) {
                indicadoresIA++;
                android.util.Log.d("QuizActivity", "  ✅ Indicador IA: Contexto narrativo");
            }

            // 3. Longitud típica de IA (más detalladas)
            if (texto.length() > 200) {
                indicadoresIA++;
                android.util.Log.d("QuizActivity", "  ✅ Indicador IA: Pregunta detallada (" + texto.length() + " chars)");
            }

            // 4. Estructura más natural y conversacional
            if (texto.contains("¿qué opinas") || texto.contains("¿cómo crees") ||
                    texto.contains("¿por qué piensas") || texto.contains("¿cuál sería")) {
                indicadoresIA++;
                android.util.Log.d("QuizActivity", "  ✅ Indicador IA: Lenguaje conversacional");
            }

            // 5. Referencias a aplicación práctica
            if (texto.contains("en la vida real") || texto.contains("en tu experiencia") ||
                    texto.contains("aplicarías") || texto.contains("utilizarías")) {
                indicadoresIA++;
                android.util.Log.d("QuizActivity", "  ✅ Indicador IA: Aplicación práctica");
            }

            android.util.Log.d("QuizActivity", "   Pregunta #" + (i+1) + ": " +
                    (texto.length() > 100 ? texto.substring(0, 100) + "..." : texto));
        }

        // Si tiene 2 o más indicadores de IA en las preguntas analizadas, probablemente es IA
        boolean pareceIA = indicadoresIA >= 2;

        android.util.Log.d("QuizActivity", "   Total indicadores IA: " + indicadoresIA + "/" + totalPreguntas);
        android.util.Log.d("QuizActivity", "   Conclusión: " + (pareceIA ? "PARECE IA" : "PARECE BANCO LOCAL"));

        return pareceIA;
    }

    // ========== Sistema de Vidas ==========

    /**
     * Inicializa el sistema de vidas (solo para niveles 2+).
     */
    private void inicializarSistemaVidas() {
        if (nivel <= 1) return;

        // Obtener userId
        int userIdInt = com.example.zavira_movil.local.TokenManager.getUserId(this);
        if (userIdInt <= 0) {
            android.util.Log.e("QuizActivity", "ERROR: userId inválido en inicializarSistemaVidas");
            return;
        }
        String userId = String.valueOf(userIdInt);

        // Inicializar vidas si no están inicializadas
        int vidas = LivesManager.getLives(this, userId, areaUi, nivel);
        if (vidas == -1) {
            LivesManager.resetLives(this, userId, areaUi, nivel);
            vidas = LivesManager.getLives(this, userId, areaUi, nivel);
        }

        // Mostrar vidas en la pantalla
        actualizarVidas();

        // Iniciar actualización periódica
        iniciarActualizacionVidas();
    }

    /**
     * Actualiza la visualización de vidas en la pantalla.
     */
    private void actualizarVidas() {
        if (nivel <= 1) {
            // Ocultar vidas para nivel 1
            if (binding.llVidasContainer != null) {
                binding.llVidasContainer.setVisibility(View.GONE);
            }
            return;
        }

        // Obtener userId
        int userIdInt = com.example.zavira_movil.local.TokenManager.getUserId(this);
        if (userIdInt <= 0) {
            return;
        }
        String userId = String.valueOf(userIdInt);

        // Obtener vidas con recarga automática
        int vidas = LivesManager.getLivesWithAutoRecharge(this, userId, areaUi, nivel);
        if (vidas == -1) {
            // No inicializado, ocultar vidas
            if (binding.llVidasContainer != null) {
                binding.llVidasContainer.setVisibility(View.GONE);
            }
            return;
        }

        // Obtener vidas parciales (media vida)
        float partialLives = LivesManager.getPartialLives(this, userId, areaUi, nivel);

        // Mostrar contenedor de vidas
        if (binding.llVidasContainer != null) {
            binding.llVidasContainer.setVisibility(View.VISIBLE);
        }

        // Obtener color del área
        int areaColor = obtenerColorArea(areaUi);

        // Limpiar corazones existentes
        LinearLayout llVidas = binding.llVidas;
        if (llVidas != null) {
            llVidas.removeAllViews();

            // Agregar corazones (3 máximo)
            for (int i = 0; i < 3; i++) {
                ImageView ivCorazon = new ImageView(this);
                LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                        dp(24), dp(24)
                );
                params.setMargins(dp(6), 0, 0, 0);
                ivCorazon.setLayoutParams(params);
                ivCorazon.setScaleType(ImageView.ScaleType.FIT_CENTER);

                if (i < vidas) {
                    // Corazón lleno del color del área
                    ivCorazon.setImageResource(R.drawable.ic_heart_filled);
                    ivCorazon.setColorFilter(areaColor, android.graphics.PorterDuff.Mode.SRC_IN);
                    llVidas.addView(ivCorazon);
                } else if (i == vidas && partialLives > 0) {
                    // Media vida: mostrar corazón medio lleno
                    // La silueta del corazón vacío debe verse completa, solo la mitad inferior del corazón lleno debe estar visible
                    android.widget.FrameLayout frameCorazon = new android.widget.FrameLayout(this);
                    LinearLayout.LayoutParams frameParams = new LinearLayout.LayoutParams(
                            dp(24), dp(24)
                    );
                    frameParams.setMargins(dp(6), 0, 0, 0);
                    frameCorazon.setLayoutParams(frameParams);

                    // Corazón vacío de fondo (silueta completa visible)
                    ImageView ivCorazonVacio = new ImageView(this);
                    android.widget.FrameLayout.LayoutParams paramsVacio = new android.widget.FrameLayout.LayoutParams(
                            android.view.ViewGroup.LayoutParams.MATCH_PARENT,
                            android.view.ViewGroup.LayoutParams.MATCH_PARENT
                    );
                    ivCorazonVacio.setLayoutParams(paramsVacio);
                    ivCorazonVacio.setScaleType(ImageView.ScaleType.FIT_CENTER);
                    ivCorazonVacio.setImageResource(R.drawable.ic_heart_empty);
                    ivCorazonVacio.setColorFilter(Color.parseColor("#CCCCCC"), android.graphics.PorterDuff.Mode.SRC_IN);

                    // Corazón lleno que solo se mostrará en la mitad inferior
                    ImageView ivCorazonLleno = new ImageView(this);
                    android.widget.FrameLayout.LayoutParams paramsLleno = new android.widget.FrameLayout.LayoutParams(
                            android.view.ViewGroup.LayoutParams.MATCH_PARENT,
                            android.view.ViewGroup.LayoutParams.MATCH_PARENT
                    );
                    ivCorazonLleno.setLayoutParams(paramsLleno);
                    ivCorazonLleno.setScaleType(ImageView.ScaleType.FIT_CENTER);
                    ivCorazonLleno.setImageResource(R.drawable.ic_heart_filled);
                    ivCorazonLleno.setColorFilter(areaColor, android.graphics.PorterDuff.Mode.SRC_IN);

                    // Aplicar clip para mostrar solo la mitad inferior del corazón lleno
                    // Usar un ViewOutlineProvider estable que calcule el outline de forma consistente
                    // Esto evita el parpadeo al mantener el outline estable entre actualizaciones
                    ivCorazonLleno.setClipToOutline(true);
                    final int heartSizePx = dp(24);
                    final int halfHeartSizePx = heartSizePx / 2;
                    ivCorazonLleno.setOutlineProvider(new android.view.ViewOutlineProvider() {
                        @Override
                        public void getOutline(android.view.View view, android.graphics.Outline outline) {
                            // Usar dimensiones de la vista si están disponibles, sino usar valores calculados
                            int width = view.getWidth() > 0 ? view.getWidth() : heartSizePx;
                            int height = view.getHeight() > 0 ? view.getHeight() : heartSizePx;
                            // Clip para mostrar solo la mitad inferior
                            outline.setRect(0, height / 2, width, height);
                        }
                    });

                    // Agregar vistas: primero el vacío (fondo), luego el lleno (con clip)
                    frameCorazon.addView(ivCorazonVacio);
                    frameCorazon.addView(ivCorazonLleno);
                    llVidas.addView(frameCorazon);
                } else {
                    // Corazón vacío
                    ivCorazon.setImageResource(R.drawable.ic_heart_empty);
                    ivCorazon.setColorFilter(Color.parseColor("#CCCCCC"), android.graphics.PorterDuff.Mode.SRC_IN);
                    llVidas.addView(ivCorazon);
                }
            }
        }

        // Actualizar tiempo de recarga
        long tiempoRestante = LivesManager.getTiempoRestanteRecarga(this, userId, areaUi, nivel);
        TextView tvTiempoRecarga = binding.tvTiempoRecarga;
        if (tvTiempoRecarga != null) {
            if (tiempoRestante > 0 && (vidas < 3 || partialLives > 0)) {
                String tiempoFormateado = LivesManager.formatearTiempoRestante(tiempoRestante);
                tvTiempoRecarga.setText("Recarga en: " + tiempoFormateado);
                tvTiempoRecarga.setVisibility(View.VISIBLE);
            } else {
                tvTiempoRecarga.setVisibility(View.GONE);
            }
        }
    }

    /**
     * Inicia la actualización periódica de vidas (cada segundo).
     */
    private void iniciarActualizacionVidas() {
        if (nivel <= 1) return;

        detenerActualizacionVidas();

        handlerVidas = new Handler(Looper.getMainLooper());
        runnableVidas = new Runnable() {
            @Override
            public void run() {
                actualizarVidas();
                // Programar siguiente actualización
                if (handlerVidas != null && runnableVidas != null) {
                    handlerVidas.postDelayed(runnableVidas, INTERVALO_ACTUALIZACION_VIDAS);
                }
            }
        };
        handlerVidas.post(runnableVidas);
    }

    /**
     * Detiene la actualización periódica de vidas.
     */
    private void detenerActualizacionVidas() {
        if (handlerVidas != null && runnableVidas != null) {
            handlerVidas.removeCallbacks(runnableVidas);
            runnableVidas = null;
        }
    }

    /**
     * Verifica si se puede recargar por detalle cuando vuelve de ver el detalle.
     */
    private void verificarRecargaPorDetalle() {
        if (nivel <= 1) return;

        // Obtener userId
        int userIdInt = com.example.zavira_movil.local.TokenManager.getUserId(this);
        if (userIdInt <= 0) {
            return;
        }
        String userId = String.valueOf(userIdInt);

        // Intentar recargar por detalle
        boolean recargado = LivesManager.recargarPorDetalle(this, userId, areaUi, nivel);
        if (recargado) {
            android.util.Log.d("QuizActivity", "Media vida recargada por detalle");
            // Mostrar mensaje
            Toast.makeText(this, "¡Media vida recargada por ver el detalle!", Toast.LENGTH_SHORT).show();
            // Actualizar vidas en la pantalla
            actualizarVidas();
        }
    }

    /**
     * Notifica la actualización del historial mediante broadcast
     */
    private void notificarActualizacionHistorial() {
        try {
            Intent intent = new Intent("com.example.zavira_movil.HISTORIAL_ACTUALIZADO");
            androidx.localbroadcastmanager.content.LocalBroadcastManager.getInstance(this)
                .sendBroadcast(intent);
        } catch (Exception e) {
            android.util.Log.e("QuizActivity", "Error al notificar actualización del historial", e);
        }
    }

    /**
     * Muestra/oculta el ProgressBar de carga
     */
    private void setLoading(boolean loading) {
        if (binding != null && binding.progress != null) {
            binding.progress.setVisibility(loading ? View.VISIBLE : View.GONE);
        }
    }

    /**
     * Muestra un diálogo informativo sobre IA ICFES
     */
    private void mostrarDialogoIA_ICFES(String area, Runnable onContinue) {
        androidx.appcompat.app.AlertDialog.Builder builder = new androidx.appcompat.app.AlertDialog.Builder(this);
        builder.setTitle(" IA ICFES");
        builder.setMessage("Estamos utilizando inteligencia artificial para optimizar tus preguntas basadas en el área de " + area + ".");
        builder.setPositiveButton("Continuar", (dialog, which) -> {
            dialog.dismiss();
            if (onContinue != null) {
                onContinue.run();
            }
        });
        builder.setCancelable(false);
        builder.show();
    }
}

package com.example.zavira_movil.resetpassword;

import android.content.Intent;
import android.os.Bundle;
import android.os.CountDownTimer;
import android.text.TextUtils;
import android.util.Patterns;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;
import android.widget.ViewFlipper;

import androidx.annotation.Nullable;
import androidx.appcompat.app.AppCompatActivity;

import com.example.zavira_movil.BasicResponse;
import com.example.zavira_movil.LoginActivity;
import com.example.zavira_movil.R;
import com.example.zavira_movil.remote.ApiService;
import com.example.zavira_movil.remote.RetrofitClient;
import com.google.android.material.textfield.TextInputEditText;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class ResetPasswordActivity extends AppCompatActivity {

    // ViewFlipper y vistas
    private ViewFlipper viewFlipper;
    private ImageView btnBack;

    // Paso 1: Solicitar código
    private EditText etCorreo;
    private Button btnEnviarCodigo;

    private ProgressBar progressStep1;

    // Paso 2: Verificar código
    private EditText etCodigo;
    private Button btnVerificarCodigo;

    private TextView tvReenviarCodigo;
    private TextView tvEmailEnviado;
    private TextView tvTimer;
    private ProgressBar progressStep2;

    // Paso 3: Nueva contraseña
    private TextInputEditText etNuevaPassword;
    private TextInputEditText etConfirmarPassword;
    private Button btnRestablecerPassword;
    private ProgressBar progressStep3;

    // Indicadores de paso
    private View indicatorStep1, indicatorStep2, indicatorStep3;

    // API
    private ApiService api;

    // Datos temporales
    private String correoActual;
    private String codigoActual;

    // Timers
    private CountDownTimer countDownTimer;  // Timer de 15 minutos
    private CountDownTimer resendTimer;     // Timer de 60 segundos para reenvío

    @Override
    protected void onCreate(@Nullable Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        android.util.Log.d("ResetPasswordActivity", "onCreate: Iniciando actividad");
        try {
            setContentView(R.layout.activity_reset_password);
            android.util.Log.d("ResetPasswordActivity", "onCreate: Layout inflado correctamente");

            // Inicializar API
            api = RetrofitClient.getInstance().create(ApiService.class);
            android.util.Log.d("ResetPasswordActivity", "onCreate: API inicializada");

            // Inicializar vistas
            initViews();
            android.util.Log.d("ResetPasswordActivity", "onCreate: Vistas inicializadas");

            setupListeners();
            android.util.Log.d("ResetPasswordActivity", "onCreate: Listeners configurados");

            // Mostrar paso 1
            showStep(0);
            android.util.Log.d("ResetPasswordActivity", "onCreate: Paso 1 mostrado - Actividad lista");
        } catch (Exception e) {
            android.util.Log.e("ResetPasswordActivity", "Error en onCreate", e);
            throw e; // Re-lanzar para que el sistema lo maneje
        }
    }



    private void initViews() {
        viewFlipper = findViewById(R.id.viewFlipper);
        btnBack = findViewById(R.id.btnBack);

        // Paso 1
        etCorreo = findViewById(R.id.etCorreo);
        btnEnviarCodigo = findViewById(R.id.btnEnviarCodigo);

        progressStep1 = findViewById(R.id.progressStep1);

        // Paso 2
        etCodigo = findViewById(R.id.etCodigo);
        btnVerificarCodigo = findViewById(R.id.btnVerificarCodigo);

        tvReenviarCodigo = findViewById(R.id.tvReenviarCodigo);
        tvEmailEnviado = findViewById(R.id.tvEmailEnviado);
        tvTimer = findViewById(R.id.tvTimer);
        progressStep2 = findViewById(R.id.progressStep2);

        // Paso 3
        etNuevaPassword = findViewById(R.id.etNuevaPassword);
        etConfirmarPassword = findViewById(R.id.etConfirmarPassword);
        btnRestablecerPassword = findViewById(R.id.btnRestablecerPassword);
        progressStep3 = findViewById(R.id.progressStep3);

        // Indicadores
        indicatorStep1 = findViewById(R.id.indicatorStep1);
        indicatorStep2 = findViewById(R.id.indicatorStep2);
        indicatorStep3 = findViewById(R.id.indicatorStep3);
    }


    // no

    private void setupListeners() {
        btnBack.setOnClickListener(v -> onBackPressed());

        // Paso 1: Enviar código
        btnEnviarCodigo.setOnClickListener(v -> solicitarCodigo());


        // Paso 2: Verificar código
        btnVerificarCodigo.setOnClickListener(v -> verificarCodigo());

        tvReenviarCodigo.setOnClickListener(v -> reenviarCodigo());

        // Paso 3: Restablecer contraseña
        btnRestablecerPassword.setOnClickListener(v -> restablecerPassword());
    }

    // ============================================
    // PASO 1: Solicitar código
    // ============================================
    private void solicitarCodigo() {
        String correo = etCorreo.getText().toString().trim();

        // Validaciones
        if (TextUtils.isEmpty(correo)) {
            etCorreo.setError("Ingresa tu correo electrónico");
            etCorreo.requestFocus();
            return;
        }

        if (!Patterns.EMAIL_ADDRESS.matcher(correo).matches()) {
            etCorreo.setError("Correo electrónico inválido");
            etCorreo.requestFocus();
            return;
        }

        // Guardar correo
        correoActual = correo;

        // Mostrar loading
        btnEnviarCodigo.setEnabled(false);
        progressStep1.setVisibility(View.VISIBLE);

        // Crear request
        SolicitarCodigoRequest request = new SolicitarCodigoRequest(correo);

        // Llamar API
        api.solicitarCodigoRecuperacion(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                btnEnviarCodigo.setEnabled(true);
                progressStep1.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isOk()) {
                    // Éxito - pasar al paso 2
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Código enviado a tu correo", Toast.LENGTH_SHORT).show();
                    showStep(1);
                    startCountDownTimer();      // Iniciar timer de 15 minutos
                    startResendTimer();         // Iniciar timer de 60 segundos
                } else {
                    // Error
                    String mensaje = "Error al enviar el código";
                    if (response.body() != null && response.body().getMessage() != null) {
                        mensaje = response.body().getMessage();
                    }
                    Toast.makeText(ResetPasswordActivity.this, mensaje, Toast.LENGTH_LONG).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                btnEnviarCodigo.setEnabled(true);
                progressStep1.setVisibility(View.GONE);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión: " + t.getMessage(), Toast.LENGTH_LONG).show();
            }
        });
    }

    // ============================================
    // PASO 2: Verificar código
    // ============================================
    private void verificarCodigo() {
        String codigo = etCodigo.getText().toString().trim();

        // Validaciones
        if (TextUtils.isEmpty(codigo)) {
            etCodigo.setError("Ingresa el código");
            etCodigo.requestFocus();
            return;
        }

        if (codigo.length() != 6) {
            etCodigo.setError("El código debe tener 6 dígitos");
            etCodigo.requestFocus();
            return;
        }

        // Guardar código
        codigoActual = codigo;

        // Mostrar loading
        btnVerificarCodigo.setEnabled(false);
        progressStep2.setVisibility(View.VISIBLE);

        // Crear request
        VerificarCodigoRequest request = new VerificarCodigoRequest(correoActual, codigo);

        // Llamar API
        api.verificarCodigoRecuperacion(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                btnVerificarCodigo.setEnabled(true);
                progressStep2.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isValid()) {
                    // Éxito - pasar al paso 3
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Código verificado correctamente", Toast.LENGTH_SHORT).show();
                    stopCountDownTimer();  // Detener timer
                    showStep(2);
                } else {
                    // Error
                    String mensaje = "Código incorrecto o expirado";
                    if (response.body() != null && response.body().getMessage() != null) {
                        mensaje = response.body().getMessage();
                    }
                    Toast.makeText(ResetPasswordActivity.this, mensaje, Toast.LENGTH_LONG).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                btnVerificarCodigo.setEnabled(true);
                progressStep2.setVisibility(View.GONE);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión: " + t.getMessage(), Toast.LENGTH_LONG).show();
            }
        });
    }

    private void reenviarCodigo() {
        // Reutilizar la función de solicitar código
        Toast.makeText(this, "Reenviando código...", Toast.LENGTH_SHORT).show();

        // Mostrar loading
        progressStep2.setVisibility(View.VISIBLE);
        tvReenviarCodigo.setEnabled(false);

        SolicitarCodigoRequest request = new SolicitarCodigoRequest(correoActual);

        api.solicitarCodigoRecuperacion(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                progressStep2.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isOk()) {
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Código reenviado exitosamente", Toast.LENGTH_SHORT).show();
                    // Reiniciar timers
                    stopCountDownTimer();
                    startCountDownTimer();
                    startResendTimer();
                } else {
                    tvReenviarCodigo.setEnabled(true);
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Error al reenviar el código", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                progressStep2.setVisibility(View.GONE);
                tvReenviarCodigo.setEnabled(true);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión", Toast.LENGTH_SHORT).show();
            }
        });
    }

    // ============================================
    // PASO 3: Restablecer contraseña
    // ============================================
    private void restablecerPassword() {
        String nuevaPassword = etNuevaPassword.getText() != null ? 
            etNuevaPassword.getText().toString().trim() : "";
        String confirmarPassword = etConfirmarPassword.getText() != null ? 
            etConfirmarPassword.getText().toString().trim() : "";

        // Validaciones
        if (TextUtils.isEmpty(nuevaPassword)) {
            etNuevaPassword.setError("Ingresa tu nueva contraseña");
            etNuevaPassword.requestFocus();
            return;
        }

        if (nuevaPassword.length() < 6) {
            etNuevaPassword.setError("La contraseña debe tener al menos 6 caracteres");
            etNuevaPassword.requestFocus();
            return;
        }

        if (TextUtils.isEmpty(confirmarPassword)) {
            etConfirmarPassword.setError("Confirma tu contraseña");
            etConfirmarPassword.requestFocus();
            return;
        }

        if (!nuevaPassword.equals(confirmarPassword)) {
            etConfirmarPassword.setError("Las contraseñas no coinciden");
            etConfirmarPassword.requestFocus();
            return;
        }

        // Mostrar loading
        btnRestablecerPassword.setEnabled(false);
        progressStep3.setVisibility(View.VISIBLE);

        // Crear request
        RestablecerPasswordRequest request = new RestablecerPasswordRequest(
            correoActual, codigoActual, nuevaPassword
        );

        // Llamar API
        api.restablecerPassword(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                btnRestablecerPassword.setEnabled(true);
                progressStep3.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isOk()) {
                    // Éxito - volver al login
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Contraseña restablecida exitosamente", Toast.LENGTH_LONG).show();

                    // Regresar al login
                    Intent intent = new Intent(ResetPasswordActivity.this, LoginActivity.class);
                    intent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_NEW_TASK);
                    startActivity(intent);
                    finish();
                } else {
                    // Error
                    String mensaje = "Error al restablecer la contraseña";
                    if (response.body() != null && response.body().getMessage() != null) {
                        mensaje = response.body().getMessage();
                    }
                    Toast.makeText(ResetPasswordActivity.this, mensaje, Toast.LENGTH_LONG).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                btnRestablecerPassword.setEnabled(true);
                progressStep3.setVisibility(View.GONE);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión: " + t.getMessage(), Toast.LENGTH_LONG).show();
            }
        });
    }

    // ============================================
    // Navegación entre pasos
    // ============================================
    private void showStep(int step) {
        viewFlipper.setDisplayedChild(step);
        updateIndicators(step);
    }

    private void updateIndicators(int currentStep) {
        // Resetear todos los indicadores
        indicatorStep1.setBackgroundColor(getResources().getColor(android.R.color.darker_gray));
        indicatorStep2.setBackgroundColor(getResources().getColor(android.R.color.darker_gray));
        indicatorStep3.setBackgroundColor(getResources().getColor(android.R.color.darker_gray));

        // Activar el indicador actual
        switch (currentStep) {
            case 0:
                indicatorStep1.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                break;
            case 1:
                indicatorStep1.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                indicatorStep2.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                break;
            case 2:
                indicatorStep1.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                indicatorStep2.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                indicatorStep3.setBackgroundColor(getResources().getColor(R.color.verde));
                break;
        }
    }

    // ============================================
    // Timers
    // ============================================

    /**
     * Inicia el timer de 15 minutos para expiración del código
     */
    private void startCountDownTimer() {
        // Cancelar timer anterior si existe
        stopCountDownTimer();

        // 15 minutos = 900,000 milisegundos
        countDownTimer = new CountDownTimer(900000, 1000) {
            @Override
            public void onTick(long millisUntilFinished) {
                // Calcular minutos y segundos
                long minutes = (millisUntilFinished / 1000) / 60;
                long seconds = (millisUntilFinished / 1000) % 60;

                // Actualizar UI
                String timeText = String.format("Tiempo restante: %02d:%02d", minutes, seconds);
                tvTimer.setText(timeText);

                // Cambiar color cuando quedan menos de 2 minutos
                if (minutes < 2) {
                    tvTimer.setTextColor(getResources().getColor(R.color.rojo));
                } else {
                    tvTimer.setTextColor(getResources().getColor(R.color.naranja));
                }
            }

            @Override
            public void onFinish() {
                tvTimer.setText("Código expirado");
                tvTimer.setTextColor(getResources().getColor(R.color.rojo));
                Toast.makeText(ResetPasswordActivity.this, 
                    "El código ha expirado. Solicita uno nuevo.", Toast.LENGTH_LONG).show();

                // Deshabilitar botón de verificar
                btnVerificarCodigo.setEnabled(false);
            }
        };

        countDownTimer.start();
    }

    /**
     * Detiene el timer de 15 minutos
     */
    private void stopCountDownTimer() {
        if (countDownTimer != null) {
            countDownTimer.cancel();
            countDownTimer = null;
        }
    }

    /**
     * Inicia el timer de 60 segundos para habilitar el botón de reenvío
     */
    private void startResendTimer() {
        // Cancelar timer anterior si existe
        if (resendTimer != null) {
            resendTimer.cancel();
        }

        // Deshabilitar botón
        tvReenviarCodigo.setEnabled(false);

        // 60 segundos = 60,000 milisegundos
        resendTimer = new CountDownTimer(60000, 1000) {
            @Override
            public void onTick(long millisUntilFinished) {
                long seconds = millisUntilFinished / 1000;
                tvReenviarCodigo.setText("Reenviar (" + seconds + "s)");
            }

            @Override
            public void onFinish() {
                tvReenviarCodigo.setText("Reenviar");
                tvReenviarCodigo.setEnabled(true);
            }
        };

        resendTimer.start();
    }

    @Override
    public void onBackPressed() {
        int currentStep = viewFlipper.getDisplayedChild();

        if (currentStep > 0) {
            // Si no está en el primer paso, volver al paso anterior
            showStep(currentStep - 1);
        } else {
            // Si está en el primer paso, cerrar la actividad
            super.onBackPressed();
        }
    }

    @Override
    protected void onResume() {
        super.onResume();
        android.util.Log.d("ResetPasswordActivity", "onResume: Actividad en primer plano");
    }

    @Override
    protected void onPause() {
        super.onPause();
        android.util.Log.d("ResetPasswordActivity", "onPause: Actividad en segundo plano");
    }

    @Override
    protected void onStop() {
        super.onStop();
        android.util.Log.d("ResetPasswordActivity", "onStop: Actividad detenida");
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        android.util.Log.d("ResetPasswordActivity", "onDestroy: Actividad destruida");
        // Limpiar timers al destruir la actividad
        stopCountDownTimer();
        if (resendTimer != null) {
            resendTimer.cancel();
        }
    }
}

package com.example.zavira_movil.resetpassword;

import android.content.Intent;
import android.os.Bundle;
import android.os.CountDownTimer;
import android.text.TextUtils;
import android.util.Patterns;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;
import android.widget.ViewFlipper;

import androidx.annotation.Nullable;
import androidx.appcompat.app.AppCompatActivity;

import com.example.zavira_movil.BasicResponse;
import com.example.zavira_movil.LoginActivity;
import com.example.zavira_movil.R;
import com.example.zavira_movil.remote.ApiService;
import com.example.zavira_movil.remote.RetrofitClient;
import com.google.android.material.textfield.TextInputEditText;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;

public class ResetPasswordActivity extends AppCompatActivity {

    // ViewFlipper y vistas
    private ViewFlipper viewFlipper;
    private ImageView btnBack;

    // Paso 1: Solicitar código
    private EditText etCorreo;
    private Button btnEnviarCodigo;

    private ProgressBar progressStep1;

    // Paso 2: Verificar código
    private EditText etCodigo;
    private Button btnVerificarCodigo;

    private TextView tvReenviarCodigo;
    private TextView tvEmailEnviado;
    private TextView tvTimer;
    private ProgressBar progressStep2;

    // Paso 3: Nueva contraseña
    private TextInputEditText etNuevaPassword;
    private TextInputEditText etConfirmarPassword;
    private Button btnRestablecerPassword;
    private ProgressBar progressStep3;

    // Indicadores de paso
    private View indicatorStep1, indicatorStep2, indicatorStep3;

    // API
    private ApiService api;

    // Datos temporales
    private String correoActual;
    private String codigoActual;

    // Timers
    private CountDownTimer countDownTimer;  // Timer de 15 minutos
    private CountDownTimer resendTimer;     // Timer de 60 segundos para reenvío

    @Override
    protected void onCreate(@Nullable Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        android.util.Log.d("ResetPasswordActivity", "onCreate: Iniciando actividad");
        try {
            setContentView(R.layout.activity_reset_password);
            android.util.Log.d("ResetPasswordActivity", "onCreate: Layout inflado correctamente");

            // Inicializar API
            api = RetrofitClient.getInstance().create(ApiService.class);
            android.util.Log.d("ResetPasswordActivity", "onCreate: API inicializada");

            // Inicializar vistas
            initViews();
            android.util.Log.d("ResetPasswordActivity", "onCreate: Vistas inicializadas");

            setupListeners();
            android.util.Log.d("ResetPasswordActivity", "onCreate: Listeners configurados");

            // Configurar OnBackPressedDispatcher
            getOnBackPressedDispatcher().addCallback(this, new androidx.activity.OnBackPressedCallback(true) {
                @Override
                public void handleOnBackPressed() {
                    int currentStep = viewFlipper.getDisplayedChild();

                    if (currentStep > 0) {
                        // Si no está en el primer paso, volver al paso anterior
                        showStep(currentStep - 1);
                    } else {
                        // Si está en el primer paso, cerrar la actividad
                        setEnabled(false);
                        getOnBackPressedDispatcher().onBackPressed();
                    }
                }
            });

            // Mostrar paso 1
            showStep(0);
            android.util.Log.d("ResetPasswordActivity", "onCreate: Paso 1 mostrado - Actividad lista");
        } catch (Exception e) {
            android.util.Log.e("ResetPasswordActivity", "Error en onCreate", e);
            throw e; // Re-lanzar para que el sistema lo maneje
        }
    }



    private void initViews() {
        viewFlipper = findViewById(R.id.viewFlipper);
        btnBack = findViewById(R.id.btnBack);

        // Paso 1
        etCorreo = findViewById(R.id.etCorreo);
        btnEnviarCodigo = findViewById(R.id.btnEnviarCodigo);

        progressStep1 = findViewById(R.id.progressStep1);

        // Paso 2
        etCodigo = findViewById(R.id.etCodigo);
        btnVerificarCodigo = findViewById(R.id.btnVerificarCodigo);

        tvReenviarCodigo = findViewById(R.id.tvReenviarCodigo);
        tvEmailEnviado = findViewById(R.id.tvEmailEnviado);
        tvTimer = findViewById(R.id.tvTimer);
        progressStep2 = findViewById(R.id.progressStep2);

        // Paso 3
        etNuevaPassword = findViewById(R.id.etNuevaPassword);
        etConfirmarPassword = findViewById(R.id.etConfirmarPassword);
        btnRestablecerPassword = findViewById(R.id.btnRestablecerPassword);
        progressStep3 = findViewById(R.id.progressStep3);

        // Indicadores
        indicatorStep1 = findViewById(R.id.indicatorStep1);
        indicatorStep2 = findViewById(R.id.indicatorStep2);
        indicatorStep3 = findViewById(R.id.indicatorStep3);
    }


    // no

    private void setupListeners() {
        btnBack.setOnClickListener(v -> onBackPressed());

        // Paso 1: Enviar código
        btnEnviarCodigo.setOnClickListener(v -> solicitarCodigo());


        // Paso 2: Verificar código
        btnVerificarCodigo.setOnClickListener(v -> verificarCodigo());

        tvReenviarCodigo.setOnClickListener(v -> reenviarCodigo());

        // Paso 3: Restablecer contraseña
        btnRestablecerPassword.setOnClickListener(v -> restablecerPassword());
    }

    // ============================================
    // PASO 1: Solicitar código
    // ============================================
    private void solicitarCodigo() {
        String correo = etCorreo.getText().toString().trim();

        // Validaciones
        if (TextUtils.isEmpty(correo)) {
            etCorreo.setError("Ingresa tu correo electrónico");
            etCorreo.requestFocus();
            return;
        }

        if (!Patterns.EMAIL_ADDRESS.matcher(correo).matches()) {
            etCorreo.setError("Correo electrónico inválido");
            etCorreo.requestFocus();
            return;
        }

        // Guardar correo
        correoActual = correo;

        // Mostrar loading
        btnEnviarCodigo.setEnabled(false);
        progressStep1.setVisibility(View.VISIBLE);

        // Crear request
        SolicitarCodigoRequest request = new SolicitarCodigoRequest(correo);

        // Llamar API
        api.solicitarCodigoRecuperacion(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                btnEnviarCodigo.setEnabled(true);
                progressStep1.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isOk()) {
                    // Éxito - pasar al paso 2
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Código enviado a tu correo", Toast.LENGTH_SHORT).show();
                    showStep(1);
                    startCountDownTimer();      // Iniciar timer de 15 minutos
                    startResendTimer();         // Iniciar timer de 60 segundos
                } else {
                    // Error
                    String mensaje = "Error al enviar el código";
                    if (response.body() != null && response.body().getMessage() != null) {
                        mensaje = response.body().getMessage();
                    }
                    Toast.makeText(ResetPasswordActivity.this, mensaje, Toast.LENGTH_LONG).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                btnEnviarCodigo.setEnabled(true);
                progressStep1.setVisibility(View.GONE);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión: " + t.getMessage(), Toast.LENGTH_LONG).show();
            }
        });
    }

    // ============================================
    // PASO 2: Verificar código
    // ============================================
    private void verificarCodigo() {
        String codigo = etCodigo.getText().toString().trim();

        // Validaciones
        if (TextUtils.isEmpty(codigo)) {
            etCodigo.setError("Ingresa el código");
            etCodigo.requestFocus();
            return;
        }

        if (codigo.length() != 6) {
            etCodigo.setError("El código debe tener 6 dígitos");
            etCodigo.requestFocus();
            return;
        }

        // Guardar código
        codigoActual = codigo;

        // Mostrar loading
        btnVerificarCodigo.setEnabled(false);
        progressStep2.setVisibility(View.VISIBLE);

        // Crear request
        VerificarCodigoRequest request = new VerificarCodigoRequest(correoActual, codigo);

        // Llamar API
        api.verificarCodigoRecuperacion(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                btnVerificarCodigo.setEnabled(true);
                progressStep2.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isValid()) {
                    // Éxito - pasar al paso 3
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Código verificado correctamente", Toast.LENGTH_SHORT).show();
                    stopCountDownTimer();  // Detener timer
                    showStep(2);
                } else {
                    // Error
                    String mensaje = "Código incorrecto o expirado";
                    if (response.body() != null && response.body().getMessage() != null) {
                        mensaje = response.body().getMessage();
                    }
                    Toast.makeText(ResetPasswordActivity.this, mensaje, Toast.LENGTH_LONG).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                btnVerificarCodigo.setEnabled(true);
                progressStep2.setVisibility(View.GONE);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión: " + t.getMessage(), Toast.LENGTH_LONG).show();
            }
        });
    }

    private void reenviarCodigo() {
        // Reutilizar la función de solicitar código
        Toast.makeText(this, "Reenviando código...", Toast.LENGTH_SHORT).show();

        // Mostrar loading
        progressStep2.setVisibility(View.VISIBLE);
        tvReenviarCodigo.setEnabled(false);

        SolicitarCodigoRequest request = new SolicitarCodigoRequest(correoActual);

        api.solicitarCodigoRecuperacion(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                progressStep2.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isOk()) {
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Código reenviado exitosamente", Toast.LENGTH_SHORT).show();
                    // Reiniciar timers
                    stopCountDownTimer();
                    startCountDownTimer();
                    startResendTimer();
                } else {
                    tvReenviarCodigo.setEnabled(true);
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Error al reenviar el código", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                progressStep2.setVisibility(View.GONE);
                tvReenviarCodigo.setEnabled(true);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión", Toast.LENGTH_SHORT).show();
            }
        });
    }

    // ============================================
    // PASO 3: Restablecer contraseña
    // ============================================
    private void restablecerPassword() {
        String nuevaPassword = etNuevaPassword.getText() != null ? 
            etNuevaPassword.getText().toString().trim() : "";
        String confirmarPassword = etConfirmarPassword.getText() != null ? 
            etConfirmarPassword.getText().toString().trim() : "";

        // Validaciones
        if (TextUtils.isEmpty(nuevaPassword)) {
            etNuevaPassword.setError("Ingresa tu nueva contraseña");
            etNuevaPassword.requestFocus();
            return;
        }

        if (nuevaPassword.length() < 6) {
            etNuevaPassword.setError("La contraseña debe tener al menos 6 caracteres");
            etNuevaPassword.requestFocus();
            return;
        }

        if (TextUtils.isEmpty(confirmarPassword)) {
            etConfirmarPassword.setError("Confirma tu contraseña");
            etConfirmarPassword.requestFocus();
            return;
        }

        if (!nuevaPassword.equals(confirmarPassword)) {
            etConfirmarPassword.setError("Las contraseñas no coinciden");
            etConfirmarPassword.requestFocus();
            return;
        }

        // Mostrar loading
        btnRestablecerPassword.setEnabled(false);
        progressStep3.setVisibility(View.VISIBLE);

        // Crear request
        RestablecerPasswordRequest request = new RestablecerPasswordRequest(
            correoActual, codigoActual, nuevaPassword
        );

        // Llamar API
        api.restablecerPassword(request).enqueue(new Callback<BasicResponse>() {
            @Override
            public void onResponse(Call<BasicResponse> call, Response<BasicResponse> response) {
                btnRestablecerPassword.setEnabled(true);
                progressStep3.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null && response.body().isOk()) {
                    // Éxito - volver al login
                    Toast.makeText(ResetPasswordActivity.this, 
                        "Contraseña restablecida exitosamente", Toast.LENGTH_LONG).show();

                    // Regresar al login
                    Intent intent = new Intent(ResetPasswordActivity.this, LoginActivity.class);
                    intent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_NEW_TASK);
                    startActivity(intent);
                    finish();
                } else {
                    // Error
                    String mensaje = "Error al restablecer la contraseña";
                    if (response.body() != null && response.body().getMessage() != null) {
                        mensaje = response.body().getMessage();
                    }
                    Toast.makeText(ResetPasswordActivity.this, mensaje, Toast.LENGTH_LONG).show();
                }
            }

            @Override
            public void onFailure(Call<BasicResponse> call, Throwable t) {
                btnRestablecerPassword.setEnabled(true);
                progressStep3.setVisibility(View.GONE);
                Toast.makeText(ResetPasswordActivity.this, 
                    "Error de conexión: " + t.getMessage(), Toast.LENGTH_LONG).show();
            }
        });
    }

    // ============================================
    // Navegación entre pasos
    // ============================================
    private void showStep(int step) {
        viewFlipper.setDisplayedChild(step);
        updateIndicators(step);
    }

    private void updateIndicators(int currentStep) {
        // Resetear todos los indicadores
        indicatorStep1.setBackgroundColor(getResources().getColor(android.R.color.darker_gray));
        indicatorStep2.setBackgroundColor(getResources().getColor(android.R.color.darker_gray));
        indicatorStep3.setBackgroundColor(getResources().getColor(android.R.color.darker_gray));

        // Activar el indicador actual
        switch (currentStep) {
            case 0:
                indicatorStep1.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                break;
            case 1:
                indicatorStep1.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                indicatorStep2.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                break;
            case 2:
                indicatorStep1.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                indicatorStep2.setBackgroundColor(getResources().getColor(R.color.blue_zavira));
                indicatorStep3.setBackgroundColor(getResources().getColor(R.color.verde));
                break;
        }
    }

    // ============================================
    // Timers
    // ============================================

    /**
     * Inicia el timer de 15 minutos para expiración del código
     */
    private void startCountDownTimer() {
        // Cancelar timer anterior si existe
        stopCountDownTimer();

        // 15 minutos = 900,000 milisegundos
        countDownTimer = new CountDownTimer(900000, 1000) {
            @Override
            public void onTick(long millisUntilFinished) {
                // Calcular minutos y segundos
                long minutes = (millisUntilFinished / 1000) / 60;
                long seconds = (millisUntilFinished / 1000) % 60;

                // Actualizar UI
                String timeText = String.format("Tiempo restante: %02d:%02d", minutes, seconds);
                tvTimer.setText(timeText);

                // Cambiar color cuando quedan menos de 2 minutos
                if (minutes < 2) {
                    tvTimer.setTextColor(getResources().getColor(R.color.rojo));
                } else {
                    tvTimer.setTextColor(getResources().getColor(R.color.naranja));
                }
            }

            @Override
            public void onFinish() {
                tvTimer.setText("Código expirado");
                tvTimer.setTextColor(getResources().getColor(R.color.rojo));
                Toast.makeText(ResetPasswordActivity.this, 
                    "El código ha expirado. Solicita uno nuevo.", Toast.LENGTH_LONG).show();

                // Deshabilitar botón de verificar
                btnVerificarCodigo.setEnabled(false);
            }
        };

        countDownTimer.start();
    }

    /**
     * Detiene el timer de 15 minutos
     */
    private void stopCountDownTimer() {
        if (countDownTimer != null) {
            countDownTimer.cancel();
            countDownTimer = null;
        }
    }

    /**
     * Inicia el timer de 60 segundos para habilitar el botón de reenvío
     */
    private void startResendTimer() {
        // Cancelar timer anterior si existe
        if (resendTimer != null) {
            resendTimer.cancel();
        }

        // Deshabilitar botón
        tvReenviarCodigo.setEnabled(false);

        // 60 segundos = 60,000 milisegundos
        resendTimer = new CountDownTimer(60000, 1000) {
            @Override
            public void onTick(long millisUntilFinished) {
                long seconds = millisUntilFinished / 1000;
                tvReenviarCodigo.setText("Reenviar (" + seconds + "s)");
            }

            @Override
            public void onFinish() {
                tvReenviarCodigo.setText("Reenviar");
                tvReenviarCodigo.setEnabled(true);
            }
        };

        resendTimer.start();
    }

    // ...existing code...

    @Override
    protected void onResume() {
        super.onResume();
        android.util.Log.d("ResetPasswordActivity", "onResume: Actividad en primer plano");
    }

    @Override
    protected void onPause() {
        super.onPause();
        android.util.Log.d("ResetPasswordActivity", "onPause: Actividad en segundo plano");
    }

    @Override
    protected void onStop() {
        super.onStop();
        android.util.Log.d("ResetPasswordActivity", "onStop: Actividad detenida");
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        android.util.Log.d("ResetPasswordActivity", "onDestroy: Actividad destruida");
        // Limpiar timers al destruir la actividad
        stopCountDownTimer();
        if (resendTimer != null) {
            resendTimer.cancel();
        }
    }
}

